const emails = $input.all();
const extractedData = [];

for (let i = 0; i < emails.length; i++) {
  const email = emails[i].json;

  let body = email.text || email.snippet || '';

  if (!body && email.textAsHtml) {
    body = email.textAsHtml;
  }

  if (body.includes('<') && body.includes('>')) {
    body = body.replace(/<[^>]*>/g, ' ')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/\s+/g, ' ')
      .trim();
  }

  body = body.split('\n')
    .filter(line => !line.trim().startsWith('>'))
    .join('\n');

  body = body.replace(/On .+ wrote:/gi, '');
  body = body.replace(/reacted via Gmail/gi, '');
  body = body.replace(/---------- Forwarded message ---------/gi, '');

  const signatureMarkers = [
    /\n--\s*\n/,
    /\n_{3,}\n/,
    /\nSent from /i,
    /\nGet Outlook for /i,
    /\nBest regards/i,
    /\nThanks,/i,
    /\nCheers/i
  ];

  for (const marker of signatureMarkers) {
    const parts = body.split(marker);
    if (parts.length > 1) {
      body = parts[0].trim();
      break;
    }
  }

  body = body.replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]+/g, ' ')
    .trim();

  if (body.length === 0) continue;

  const subject = email.subject || '(No subject)';
  const date = email.date || email.receivedDateTime || '';
  const snippet = body.substring(0, 150) + (body.length > 150 ? '...' : '');

  let fromAddress = '';
  let fromName = '';

  if (email.from && email.from.value && email.from.value[0]) {
    fromAddress = email.from.value[0].address || '';
    fromName = email.from.value[0].name || '';
  } else if (email.from && typeof email.from === 'string') {
    fromAddress = email.from;
    if (fromAddress.includes('<')) {
      const match = fromAddress.match(/^(.+?)\s*<(.+?)>$/);
      if (match) {
        fromName = match[1].trim();
        fromAddress = match[2].trim();
      }
    }
  }

  if (!fromName && fromAddress) {
    fromName = fromAddress.split('@')[0];
  }

  extractedData.push({
    emailNumber: i + 1,
    emailId: email.id || email.messageId || `email_${i}`,
    subject,
    body,
    snippet,
    date,
    from: fromAddress,
    fromName
  });
}

return extractedData.map(item => ({ json: item }));

const emails = $input.all();
const cleanedEmails = [];

for (const item of emails) {
  const email = item.json;

  if (!email || !email.body || typeof email.body !== 'string' || email.body.trim().length === 0) {
    cleanedEmails.push({ json: { emailId: email?.emailId || 'unknown', subject: email?.subject || 'No subject', error: 'Empty or invalid body', skipped: true } });
    continue;
  }

  let cleanBody = email.body
    .replace(/reacted via Gmail/gi, '')
    .replace(/\[cid:.*?\]/g, '')
    .replace(/\r\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]+/g, ' ')
    .trim();

  const signatureMarkers = [/\n--\s*\n/, /\n_{3,}\n/, /\nSent from /i, /\nGet Outlook for /i, /\nBest regards/i, /\nThanks/i];
  for (const marker of signatureMarkers) {
    const parts = cleanBody.split(marker);
    if (parts.length > 1) cleanBody = parts[0].trim();
  }

  const wordArray = cleanBody.split(/\s+/).filter(w => w.length > 0);
  const wordCount = wordArray.length;

  if (wordCount === 0) {
    cleanedEmails.push({ json: { emailId: email.emailId, subject: email.subject, error: 'Empty after cleaning', skipped: true } });
    continue;
  }

  const totalCharsNoSpaces = cleanBody.replace(/\s/g, '').length;
  const avgWordLength = totalCharsNoSpaces / wordCount;
  const sentences = cleanBody.match(/[.!?]+(?=\s|$)/g) || [];
  const sentenceCount = sentences.length || 1;
  const avgSentenceLength = wordCount / sentenceCount;
  const exclamationCount = (cleanBody.match(/!/g) || []).length;
  const questionCount = (cleanBody.match(/\?/g) || []).length;
  const emojiMatches = cleanBody.match(/[\u{1F300}-\u{1F9FF}]|[\u{2600}-\u{26FF}]/gu) || [];
  const emojiCount = emojiMatches.length;
  const startsWithGreeting = /^(hi|hello|hey|dear|bonjour|salut|hola)/i.test(cleanBody);
  const hasFormalClosing = /(best regards|sincerely|regards|cordialement|salutations)/i.test(cleanBody);
  const usesContractions = /(i'm|you're|don't|can't|won't)/i.test(cleanBody);
  const uppercaseWords = cleanBody.match(/\b[A-Z]{2,}\b/g) || [];
  const uppercaseRatio = uppercaseWords.length / (wordCount || 1);
  const numberCount = (cleanBody.match(/\b\d+\b/g) || []).length;
  const urlCount = (cleanBody.match(/https?:\/\/[^\s]+/g) || []).length;

  let formalityScore = 5;
  if (hasFormalClosing) formalityScore += 2;
  if (avgWordLength > 6) formalityScore += 1;
  if (avgSentenceLength > 20) formalityScore += 1;
  if (usesContractions) formalityScore -= 1;
  if (emojiCount > 0) formalityScore -= 2;
  if (exclamationCount > 2) formalityScore -= 1;
  formalityScore = Math.max(0, Math.min(10, formalityScore));

  let contentType = 'conversational';
  if (numberCount > wordCount * 0.3) contentType = 'data-heavy';
  else if (urlCount > 2) contentType = 'informational';
  else if (formalityScore >= 7) contentType = 'formal';
  else if (formalityScore <= 3) contentType = 'casual';

  let tone = 'neutral';
  if (exclamationCount > 2 && emojiCount > 0) tone = 'enthusiastic';
  else if (questionCount > exclamationCount * 2) tone = 'inquisitive';
  else if (formalityScore >= 7) tone = 'professional';
  else if (formalityScore <= 3 && usesContractions) tone = 'friendly';

  cleanedEmails.push({
    json: {
      emailId: email.emailId, subject: email.subject, date: email.date,
      from: email.from, cleanBody,
      preview: cleanBody.substring(0, 150) + (cleanBody.length > 150 ? '...' : ''),
      wordCount, avgWordLength: Math.round(avgWordLength * 10) / 10,
      sentenceCount, avgSentenceLength: Math.round(avgSentenceLength * 10) / 10,
      exclamationCount, questionCount,
      emojiCount, hasEmojis: emojiCount > 0,
      startsWithGreeting, hasFormalClosing, usesContractions,
      uppercaseRatio: Math.round(uppercaseRatio * 100) / 100,
      numberCount, urlCount, formalityScore, contentType, tone, skipped: false
    }
  });
}

return cleanedEmails;

const allItems = $('Analyze Writing Style').all();
const validItems = allItems.filter(item => !item.json.skipped);

if (validItems.length === 0) return [{ json: { error: 'No valid emails to build profile from' } }];

let totalWordCount = 0, totalSentenceLength = 0, totalFormality = 0, totalEmojis = 0;
let emojiCount = 0, contractionCount = 0, formalClosingCount = 0, greetingCount = 0;
const tones = [], contentTypes = [], samples = [];

for (const item of validItems) {
  const d = item.json;
  totalWordCount += d.wordCount || 0;
  totalSentenceLength += d.avgSentenceLength || 0;
  totalFormality += d.formalityScore || 0;
  totalEmojis += d.emojiCount || 0;
  if (d.hasEmojis) emojiCount++;
  if (d.usesContractions) contractionCount++;
  if (d.hasFormalClosing) formalClosingCount++;
  if (d.startsWithGreeting) greetingCount++;
  if (d.tone) tones.push(d.tone);
  if (d.contentType) contentTypes.push(d.contentType);
  if (samples.length < 3 && d.cleanBody && d.cleanBody.length > 20) samples.push(d.cleanBody.substring(0, 300));
}

const total = validItems.length;
function mostCommon(arr) {
  if (!arr.length) return 'conversational';
  return arr.sort((a, b) => arr.filter(v => v === b).length - arr.filter(v => v === a).length)[0];
}

const firstItem = validItems[0].json;
const userEmail = firstItem.from || '';
const userName = firstItem.fromName || userEmail.split('@')[0] || 'User';

return [{ json: {
  last_updated: new Date().toISOString(),
  email: userEmail,
  name: userName,
  avg_word_count: Math.round(totalWordCount / total),
  avg_sentence_length: Math.round((totalSentenceLength / total) * 10) / 10,
  avg_formality: Math.round(totalFormality / total),
  uses_emojis: emojiCount > total * 0.2 ? 'TRUE' : 'FALSE',
  avg_emoji_count: Math.round((totalEmojis / total) * 10) / 10,
  uses_contractions: contractionCount > total * 0.3 ? 'TRUE' : 'FALSE',
  has_formal_closing: formalClosingCount > total * 0.5 ? 'TRUE' : 'FALSE',
  starts_with_greeting: greetingCount > total * 0.5 ? 'TRUE' : 'FALSE',
  most_common_tone: mostCommon(tones),
  most_common_content_type: mostCommon(contentTypes),
  sample_email_1: samples[0] || '',
  sample_email_2: samples[1] || '',
  sample_email_3: samples[2] || '',
  total_emails_analyzed: total
}}];

const inputData = $input.first().json;

return [{
  json: {
    model: "llama-3.3-70b-versatile",
    messages: [
      {
        role: "system",
        content: "You are an email assistant. Match the user's writing style exactly. Be natural and professional."
      },
      {
        role: "user",
        content: inputData.prompt
      }
    ],
    max_tokens: 500,
    temperature: 0.7
  }
}];

const gmailData = $('Filter Email').first().json;
const from = gmailData.from || 'Unknown Sender';
const subject = gmailData.subject || 'No subject';
const body = gmailData.body || 'No content available';
const threadId = gmailData.threadId || '';

let senderFirstName = '', senderFullName = '';
if (from.includes('<')) {
  const namePart = from.split('<')[0].trim();
  senderFullName = namePart;
  senderFirstName = namePart.split(' ')[0];
} else if (from.includes('@')) {
  const emailPrefix = from.split('@')[0];
  senderFirstName = emailPrefix.charAt(0).toUpperCase() + emailPrefix.slice(1);
  senderFullName = senderFirstName;
} else {
  senderFirstName = from.split(' ')[0] || '';
  senderFullName = from;
}

let myName = 'User', myEmail = '', avgWordCount = 80, avgSentenceLength = 15;
let avgFormality = 6, hasEmojis = false, avgEmojiCount = 0, hasContractions = true;
let hasFormalClosing = true, startsWithGreeting = true, mostCommonTone = 'neutral';
let mostCommonType = 'conversational', sampleEmails = [], totalEmailsAnalyzed = 0;

try {
  const profileRow = $('Get row(s) in sheet').first().json;
  myEmail = profileRow.email || '';
  myName = profileRow.name || myEmail.split('@')[0] || 'User';
  avgWordCount = parseInt(profileRow.avg_word_count) || 80;
  avgSentenceLength = parseFloat(profileRow.avg_sentence_length) || 15;
  avgFormality = parseInt(profileRow.avg_formality) || 6;
  hasEmojis = profileRow.uses_emojis === 'TRUE';
  avgEmojiCount = parseFloat(profileRow.avg_emoji_count) || 0;
  hasContractions = profileRow.uses_contractions === 'TRUE';
  hasFormalClosing = profileRow.has_formal_closing === 'TRUE';
  startsWithGreeting = profileRow.starts_with_greeting === 'TRUE';
  mostCommonTone = profileRow.most_common_tone || 'neutral';
  mostCommonType = profileRow.most_common_content_type || 'conversational';
  totalEmailsAnalyzed = parseInt(profileRow.total_emails_analyzed) || 0;
  if (profileRow.sample_email_1) sampleEmails.push(profileRow.sample_email_1);
  if (profileRow.sample_email_2) sampleEmails.push(profileRow.sample_email_2);
  if (profileRow.sample_email_3) sampleEmails.push(profileRow.sample_email_3);
} catch (error) {
  console.log('Could not load profile, using defaults');
}

myName = myName.charAt(0).toUpperCase() + myName.slice(1);
const userFirstName = myName.split(' ')[0];

function analyzeIncomingEmail(subjectText, bodyText) {
  const combined = (subjectText + ' ' + bodyText).toLowerCase();
  const isUrgent = ['urgent', 'asap', 'immediately', 'deadline'].some(w => combined.includes(w));
  const hasQuestion = bodyText.includes('?') || combined.includes('could you') || combined.includes('can you');
  const casualCount = ['hi', 'hey', 'thanks', "i'm", '!'].filter(m => combined.includes(m)).length;
  const formalCount = ['dear', 'regards', 'sincerely', 'kindly'].filter(m => combined.includes(m)).length;
  let senderFormality = 'neutral';
  if (formalCount > casualCount + 1) senderFormality = 'formal';
  else if (casualCount > formalCount + 1) senderFormality = 'casual';
  const hasGratitude = ['thank', 'thanks', 'appreciate'].some(w => combined.includes(w));
  const hasComplaint = ['disappointed', 'problem', 'issue', 'concern'].some(w => combined.includes(w));
  let emotionalTone = 'neutral';
  if (hasGratitude) emotionalTone = 'grateful';
  if (hasComplaint) emotionalTone = 'complaint';
  const wordCount = bodyText.split(/\s+/).length;
  const isShort = wordCount < 30;
  const hasDelayMention = ['late', 'delay', 'waiting', 'follow up'].some(i => combined.includes(i));
  return { isUrgent, hasQuestion, senderFormality, emotionalTone, isShort, wordCount, hasDelayMention };
}

const emailContext = analyzeIncomingEmail(subject, body);
const incomingTextSample = (subject + ' ' + body).substring(0, 600);

const prompt = `You are ${myName} (${myEmail}) replying to an email from ${senderFullName || senderFirstName}.

INCOMING EMAIL:
From: ${from}
Subject: "${subject}"
Message: "${body}"

CONTEXT:
- Urgency: ${emailContext.isUrgent ? 'HIGH' : 'Normal'}
- Type: ${emailContext.hasQuestion ? 'Question/Request' : 'Statement/Update'}
- Sender tone: ${emailContext.senderFormality} / ${emailContext.emotionalTone}
- Length: ${emailContext.isShort ? 'Short — keep reply brief' : 'Detailed'}

YOUR WRITING STYLE (from ${totalEmailsAnalyzed} analyzed emails):
- Length: ~${avgWordCount} words
- Formality: ${avgFormality}/10
- Emojis: ${hasEmojis ? `yes (avg ${avgEmojiCount}/email)` : 'no'}
- Contractions: ${hasContractions ? 'yes' : 'no'}
- Greeting: ${startsWithGreeting ? 'always greets' : 'sometimes skips'}
- Closing: ${hasFormalClosing ? 'formal closing' : 'casual sign-off'}
- Tone: ${mostCommonTone}

${sampleEmails.length > 0 ? `EXAMPLES OF YOUR WRITING:
${sampleEmails.map((s, i) => `Example ${i+1}: "${s}"`).join('\n')}` : ''}

LANGUAGE RULE: Detect the language of the incoming email and reply in THAT EXACT SAME language.

Write the reply now. Structure: greeting → answer → closing → sign as "${userFirstName}"
OUTPUT: Only the reply. No subject line, no explanations.`;

return [{
  json: {
    prompt,
    original_subject: subject,
    original_from: from,
    original_body: body,
    thread_id: threadId,
    sender_name: senderFirstName,
    context: emailContext,
    detected_user_name: myName,
    detected_user_email: myEmail,
    style_source: `Profile — ${totalEmailsAnalyzed} emails`
  }
}];

const items = $('Gmail Trigger').all();

const results = items.map(item => {
  const data = item.json;
  const fromEmail = data.from?.value?.[0]?.address || '';
  const fromName = data.from?.value?.[0]?.name || '';
  const subject = data.subject || '';
  const body = data.snippet || data.bodyPlainText || data.text || '';
  const threadId = data.threadId || data.id || '';
  const labelIds = data.labelIds || [];

  const hasPromotionalLabel = labelIds.some(label =>
    ['CATEGORY_PROMOTIONS','CATEGORY_SOCIAL','CATEGORY_UPDATES','CATEGORY_FORUMS'].includes(label)
  );
  if (hasPromotionalLabel) return { json: { action: 'SKIPPED', reason: 'Promotional category', from: fromEmail, subject } };

  const skipPatterns = ['no-reply','noreply','donotreply','notifications@','notify@','alerts@','newsletter@','marketing@'];
  if (skipPatterns.some(p => fromEmail.toLowerCase().includes(p))) return { json: { action: 'SKIPPED', reason: 'Automated sender', from: fromEmail } };

  const promoKeywords = ['unsubscribe','newsletter','promotion','deal','offer','discount','sale'];
  if (promoKeywords.some(k => subject.toLowerCase().includes(k))) return { json: { action: 'SKIPPED', reason: 'Promotional subject', subject } };

  if (!fromEmail) return { json: { action: 'SKIPPED', reason: 'Missing sender' } };

  return { json: { action: 'CONTINUE', threadId, from: fromEmail, fromName, subject, body, labelIds } };
});

return results;

const groqResponse = $('HTTP Request').first().json;
let replyText = groqResponse.choices?.[0]?.message?.content || '';

function decodeHTMLEntities(text) {
  const entities = { '&#39;': "'", '&apos;': "'", '&quot;': '"', '&amp;': '&', '&lt;': '<', '&gt;': '>', '&nbsp;': ' ', '&#233;': 'é', '&#232;': 'è', '&#234;': 'ê', '&#244;': 'ô', '&#231;': 'ç', '&#224;': 'à', '&#249;': 'ù' };
  let decoded = text;
  for (const [entity, char] of Object.entries(entities)) decoded = decoded.split(entity).join(char);
  decoded = decoded.replace(/&#(\d+);/g, (_, dec) => String.fromCharCode(dec));
  decoded = decoded.replace(/&#x([0-9A-Fa-f]+);/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)));
  return decoded;
}

const cleanedReply = decodeHTMLEntities(replyText);

return [{
  json: {
    reply_body: cleanedReply,
    original_response: replyText,
    thread_id: $('Build Personalized Prompt').first().json.thread_id || '',
    subject: $('Build Personalized Prompt').first().json.original_subject || ''
  }
}];

const body = $input.first().json.body || "";

const injectionPatterns = [
  /ignore previous instructions/i,
  /disregard.*instructions/i,
  /you are now/i,
  /act as/i,
  /new persona/i,
  /forget.*instructions/i,
  /system prompt/i,
  /\[INST\]/i,
  /<\|.*\|>/i
];

const isSuspicious = injectionPatterns.some(p => p.test(body));

return [{ json: { ...$input.first().json, skip: isSuspicious } }];

const crypto = require('crypto');

// ⚠️ Replace with your own 32-byte hex key (set in environment or n8n credentials)
const KEY = process.env.ENCRYPTION_KEY || 'REPLACE_WITH_YOUR_32_BYTE_HEX_KEY';

function encrypt(text) {
  if (!text) return null;
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', Buffer.from(KEY, 'hex'), iv);
  let encrypted = cipher.update(String(text), 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const authTag = cipher.getAuthTag().toString('hex');
  const ivHex = Array.from(iv).map(b => b.toString(16).padStart(2, '0')).join('');
  return `${ivHex}:${authTag}:${encrypted}`;
}

function sanitize(text, maxLen = 300) {
  if (!text) return '';
  return String(text).replace(/<[^>]*>/g, '').replace(/[\x00-\x1F]/g, '').trim().substring(0, maxLen);
}

const item = $input.item.json;

return {
  sender_email: encrypt(item.from || item.sender_email),
  sender_name: encrypt(item.sender_name || item.name),
  email_body: encrypt(item.body || item.draft || item.text),
  subject: sanitize(item.subject, 200),
  status: item.status || 'processed',
  validated: item.validated,
  validated_at: item.validated_at,
  processed_at: new Date().toISOString()
};

const item = $input.item.json;

const content = item.reply_body || item.original_response || item.text || item.body;
if (!content) throw new Error('[Output Validator] No content to validate');

const errors = [];

const urlPattern = /https?:\/\/(?!mail\.google\.com|accounts\.google\.com)[^\s"'<>]+/gi;
const suspiciousUrls = content.match(urlPattern) || [];
if (suspiciousUrls.length > 0) errors.push(`Suspicious URLs detected: ${suspiciousUrls.join(', ')}`);

const scriptPattern = /<script[\s\S]*?>[\s\S]*?<\/script>|javascript:|on\w+\s*=/gi;
if (scriptPattern.test(content)) errors.push('Script injection detected in AI response');

const leakagePatterns = [/you are an ai/i, /as an ai language model/i, /my instructions are/i, /system prompt/i, /ignore previous/i];
for (const pattern of leakagePatterns) {
  if (pattern.test(content)) { errors.push('Prompt leakage detected'); break; }
}

if (content.length > 5000) errors.push(`Response too long: ${content.length} chars`);
if (content.trim().length < 10) errors.push('Response too short');

if (errors.length > 0) throw new Error(`[Output Validator] Blocked: ${errors.join(' | ')}`);

return { ...item, validated: true, validated_at: new Date().toISOString() };

const crypto = require('crypto');

// ⚠️ Replace with your own 32-byte hex key (set in environment or n8n credentials)
const SECRET_KEY = process.env.HASH_SECRET || 'REPLACE_WITH_YOUR_32_BYTE_HEX_KEY';

const item = $input.item.json;
const content = item.email_body || item.reply_body || item.subject || '';
if (!content) throw new Error('[Hash & Sign] No content found to sign');

const payload = JSON.stringify({
  content: content.trim(),
  sender_email: item.sender_email || '',
  draft_id: item.message?.id || item.id || '',
  timestamp: new Date().toISOString()
});

const signature = crypto.createHmac('sha256', SECRET_KEY).update(payload).digest('hex');
const payload_hash = crypto.createHash('sha256').update(payload).digest('hex');

return {
  ...item,
  draft_id: item.message?.id || item.id || '',
  thread_id: item.message?.threadId || '',
  _integrity: { signature, payload_hash, signed_at: new Date().toISOString(), algorithm: 'hmac-sha256' }
};
